  "feature": "大花楼木织机上下两层，楼上拽花工按花本提经，楼下织手妆金敷彩、抛梭织纬，两人以口诀与节拍同步。织机由1924个木部件构成，机上经线数以千计，连接控制它们的线线数以万计。妆花的核心是通经断纬的挖花：通梭织地，局部以小梭挖织，同一纬向可现十余色，金线、孔雀羽皆可入织，故称“逐花异色”。挑花结本则是用结绳的方式把花纹、图案、色彩编成织机可读取的程序，相当于前数字时代的软件。全工艺分纹样设计、意匠、挑花结本、造机、织造五部分，细分工序过百，是三大名锦中唯一仍以手工挖花为主的一支。",
