  "bio": "1955年生于南京。1973年18岁进入南京云锦研究所，师从顾惠源，从艺五十余年，精通云锦织造全部工序。1983年起负责古代丝绸文物研究与复制，参与复制失传三百余年的“织金孔雀羽妆花纱龙袍料”及“黄地织金妆花缎过肩通袖直身龙栏袍料”，并参与二经绞纱、四经绞罗等失传织锦工艺的恢复研制。2007年参与编写《中国南京云锦》及《南京云锦企业标准》，把织造工序写成可执行的工艺规程。目前团队在南京市莫愁中等专业学校开设云锦织造课程，以产教融合培养中青年骨干。他的价值不只在于“能织”，更在于能把挑花结本的编程逻辑讲给公众听。",
  "history": "1500多年前史籍已有南京丝织品的文字记载，但无实物流传。东晋末年，南京设立专门生产织锦的机构斗场锦署。北宋南迁后，南京成为全国丝织中心。织金饰约始于元代，彩色妆花织金饰则盛行于明清两代。清康熙至嘉庆年间，南京云锦生产规模达到顶峰：木织机3万多台，20余万人以此为业，年产锦缎上百万匹，产值在3000万两白银以上。清末云锦业走向衰落，至1949年南京解放时，全市能生产的云锦织机只剩4台。1949年后经抢救、扶持和保护逐步恢复。2006年列入第一批国家级非遗，2009年作为“中国传统桑蚕丝织技艺”组成部分入选人类非遗代表作名录。",
  "meaning": "云锦的文化内涵，首先在于“织成”龙袍所体现的身体—衣冠—宇宙秩序的合一。龙袍按人体各部位整幅设计，织成后裁片拼接，追求“天衣无缝”，衣冠在此不是遮蔽身体的物件，而是将身体纳入一套礼制秩序的媒介。其次，挑花结本的本质是前数字时代的编程思维——用结绳的方式把视觉信息转译为机械动作序列，这种“以绳记事、以结传纹”的智慧，与今天的软件编程在逻辑上同构。传承上，南京云锦研究所成功复制了定陵明万历皇帝龙袍、马王堆素纱蝉衣等文物，周双喜、金文等传承人同时承担复制、教学与公众讲解三重角色。云锦面临的真正困难不在于技艺失传，而在于学艺周期长、劳动强度大、市场对纯手工妆花的需求持续萎缩，青年从业意愿低。",
  "chain": "纹样设计→意匠→挑花结本→造机→织造，细分工序超过百道",
