  "feature": "核心是通经断纬：生蚕丝作经、彩色熟蚕丝作纬，经线贯通全幅不断，纬线只在需要该色的局部往返，变一色即换一梭。基本技法只有四种，区别在色块边缘的收口与过渡——结用于清晰界定边界，掼用于相邻色块衔接，勾用于勾勒细线，戗用于渐变。因纬线断头，花纹与地部之间留下一道细裂，迎光如刀刻之痕，故名“刻丝”；也正因纬线不贯通，织物正反如一，没有正反面之分。熟练织工日织寸许，一件作品常经年累月，古人以“一寸缂丝一寸金”“织中之圣”称之。",
