    "a": "按勾好的边界把画面拆成若干独立色块，一块一梭。数十只舟形竹梭依次排开，每只只装一种色号的熟丝纬线，梭上贴签记色，取错一梭整块颜色就错。色块拆分要考虑织序：一般先织地部、后织花纹，先大块、后小块，小块压在先织的色块边缘上，收口才干净。同色但不相连的两块，可以共用一梭，但要记住往返路径。",
