    "n": "小梭挖织",
    "a": "按色块逐块缂织，纬线不贯穿整幅，只在需要该色的局部往返，到边界就回梭收口，变一色即换一梭。收口靠四种基本技法：结，用于色块边缘的清晰界定，纬线在边界处回折打结；掼，用于相邻色块的衔接，两色纬线互相搭接一针；勾，用于勾勒细线轮廓，单梭勾出一道边；戗，用于色彩渐变，长短戗、凤尾戗、参合戗、包心戗各按渐变方向排梭。熟练织工日织寸许。",
