    "a": "每织入一段纬线，立刻用木梳形拨子把纬线向织口方向排紧打实。拨子的齿要顺着经线插入，一下一下推，不能横刮——横刮会把经线拨乱。排紧的标准是纬线之间不留缝隙、经线不露白，用指甲横划织面应有细密的阻力感。密度不匀的地方迎光会显出深浅不一的横档，这是缂丝最容易被看出的瑕疵。",
