  "bio": "苏州缂丝代表性人物，中国工艺美术大师，第一批国家级代表性传承人，2007年被列为国家级传承人。在苏州市落瓜桥下塘设有工作室，长期从事缂丝织造与教学；其工作室2023年评估合格，继续担任该项目的保护单位。他以摹缂书画见长，把结、掼、勾、戗四种基本技法背后的判断逻辑讲成可传授的语言，使一门高度依赖手感的技艺获得可传递的形式。",
  "history": "缂丝起源于汉魏时期。南宋随朝廷南迁，在苏州陆慕等地形成产业中心。明代发展为宫廷御用龙袍缂织和书画缂丝两大方向。清代出现缂绘结合的新技法。20世纪70至80年代，苏州成立五家缂丝厂，开发出双面全异缂丝《寿星图》等创新作品。2006年列入第一批国家级非遗，2009年作为“中国传统桑蚕丝织技艺”组成部分入选人类非遗代表作名录。王金山2007年被列为国家级传承人，其工作室2023年评估合格继续担任项目保护单位。",
  "meaning": "缂丝的文化分量，全在一个“断”字。纬线不贯通，意味着每一色都要在边界处“停笔收锋”，织工在投梭之前就已经在脑中完成了色彩的分解与边界的设计。这种以“断”求“全”的工艺逻辑，使缂丝天然地接近于绘画——它不是在“织一块布”，而是在“用丝线摹写一幅画”。正因如此，缂丝长期服务于书画复制和宫廷袍服，兼具工艺与艺术双重身份，古人以“一寸缂丝一寸金”和“织中之圣”称之。传承上，王金山一代人的贡献不仅在于织，更在于把四种基本技法背后的判断逻辑讲清楚，使一门高度依赖手感的技艺获得可传递的语言形式。",
  "chain": "勾样→分色分块→小梭挖织→拨子排紧纬线；基本技法只有结、掼、勾、戗四种",
  "herFull": "国家级非遗；2009年人类非遗代表作名录。",
