  "bio": "1939年12月生。1954年进入江苏省丝绸工业学校学习丝织专业，1957年进入苏州丝绸研究所，1966年起对宋锦进行挖掘与研究。她复原宋锦花楼织机，与中国国家博物馆等单位合作复制先秦、两汉、隋唐、明清珍贵丝绸文物二十余件，包括商代“雷纹花绮”、战国“舞人动物纹锦”、西汉“绛地红花鹿纹锦”等；又以丝为材设计出人造血管，填补国内空白。作为宋锦织造技艺唯一的国家级代表性传承人，她著有《中国宋锦》，系统解析组织结构与二十余道工序；任苏州大学兼职教授，坚持授徒传艺。",
  "history": "宋锦以宋代织锦传统为源头，在组织结构和色彩工艺上形成独立体系。2006年列入第一批国家级非遗，2009年作为“中国传统桑蚕丝织技艺”组成部分入选人类非遗代表作名录。钱小萍作为宋锦织造技艺唯一的国家级代表性传承人，复原宋锦花楼织机，并以《中国宋锦》一书系统解析其组织结构与二十余道工序。",
  "meaning": "宋锦的文化性格可以概括为“华而不显”。它以几何骨架配花卉纹样，色彩丰富但不以金碧辉煌取胜，质地坚柔轻薄，既服务于服饰，也深度嵌入书画装裱传统——中国书画的“装池”之美，在很大程度上依赖宋锦的质感与色调。2014年APEC领导人“新中装”采用宋锦面料，使这一技艺重新进入当代公共视野。传承上，钱小萍的工作兼具复原、著述、教学三重意义：复原花楼织机解决了“能不能织”的问题，著述解决了“怎么讲清楚”的问题，而传承人培养解决的才是“谁来织”的问题。",
  "chain": "缫丝→染色→设计→意匠→挑花结本→上机织造，一般二十多道工序",
  "herFull": "国家级非遗；2009年人类非遗代表作名录。",
