  "bio": "第一批国家级代表性传承人。1951年进入成都蜀锦厂，参与复制“花楼织机”；1983年至1993年受委派先后到美国芝加哥、纽约、瑞士等地，用花楼织机现场表演织锦技艺。2002年后，他与几位老同事修复了传自清代的花楼织机，使老机重新可织。他将力学与美学结合，在实用与观赏之间取得平衡，是馆内少数能独立操作老式花楼织机的匠人。",
  "history": "蜀锦历史最久，花楼织机可溯至三国时期，距今一千八百余年。叶永洲1951年进入成都蜀锦厂，参与复制花楼织机；1983年至1993年受委派先后到美国芝加哥、纽约、瑞士等地用花楼织机表演织锦技艺。2002年后，叶永洲与几位老同事修复了传自清代的花楼织机。2006年列入第一批国家级非遗，2009年作为“中国传统桑蚕丝织技艺”组成部分入选人类非遗代表作名录。",
  "meaning": "蜀锦的9680次投梭、9680次提拉、9680次打纬，不是修辞性的数字，而是一寸锦缎所凝结的时间密度的直接计量。经锦以经线显花，意味着图案的“骨架”在整经阶段就已经被规定，织造过程更像是在一个预先设定的经线秩序中填入纬线——这种工艺逻辑赋予蜀锦一种秩序感极强的装饰性格。叶永洲将力学与美学结合，使织锦在实用与观赏之间取得平衡。传承的核心困境与云锦相似：花楼织机的操作需要两人长期配合的默契，而这种默契无法被拆解为标准化教材。",
  "chain": "纹样设计→挑花结本→装机→挽花工提经、梭工投梭→打纬",
