  "feature": "先染后织的扎经染色，图案不画在布面而描在经线上，俗称“经线显花”。工序达28道：煮茧、抽丝、并丝、卷线、扎经、分层染色、整经、分线、上机、织绸，全部手工。技术要害在扎经——把经线分成若干股、描点定位，用玉米皮包裹不需染色的段，扎结松紧直接决定染液渗入的程度。染色有严格次序：先染大块与浅色，再染小块与深色，每染一色晾干后重新扎结，反复多轮。扎结处染液自然渗入，形成边缘模糊、色块互晕的肌理，机染难以复制。以素纬与彩经交织，经浮线在表面显花，纹样多为石榴、巴旦木、羊角等几何化母题。",
