    "n": "分层染色",
    "a": "染色有严格的先后：先染大块和浅色部分，再染小块和深色部分。每染完一色，晾干，再对新的不需染色段重新扎结，再染下一色，如此反复多次。顺序不能颠倒——先染深色，浅色就盖不住。染液浓度、浸染时间、扎结松紧三个变量共同决定最终色相，同一缸染出的两匹也不会完全相同。",
    "t": "染缸、天然染料",
