    "n": "整经与分线",
    "a": "全部染完、晾透后解去扎结物。解的时候要按原顺序，一股一股解，乱了次序整幅纹样就错位。解开后按织造幅宽整经，把经线逐根分到筘齿，再一卷一卷上机。分线时要检查晕散是否连贯——同一纹样的上下两段若晕散宽度差太多，说明扎结时松紧失控，这一段织出来会是花的。",
    "t": "经架、织机",
