    "a": "用梳毛板把晒干的羊毛逐把梳开，梳去残留的草屑、硬梗与短碎毛。梳的方向要顺毛流，逆向会拉断纤维。梳到毛束松散、纤维平行，手抓一把能从指缝间均匀漏下为止。梳得透，后面捻线才匀；梳不透，线里夹着硬梗，织出来硌手、易断。",
    "t": "梳毛板",
    "h": "约数天（估）",
    "d": "中",
    "k": "硬梗梳不净，捻线时断头，织造中断经就要停机接。",
