    "a": "上织机，经线按色条排列——邦典以条纹或几何纹为主，色条的宽度与排列因地区和家族传统而异，杰德秀的斜玛条纹最细。织造时纬线粗实，打纬要沉，把粗纬压进去，织面才有厚度。色条交接处要换线，换线的头藏在条缝里。一条邦典的条纹数、色序就是它的身份，织错了买家一眼看出。",
    "t": "织机",
