  "bio": "格桑为第一批国家级非遗项目“藏族邦典、卡垫织造技艺”代表性传承人，杰德秀镇格桑围裙农民合作社创立者之一。其女旦增卓嘎为全国劳动模范，已成为杰德秀邦典编织技艺的重要传承力量；嘎日同为该技艺的重要传承人。传承以家庭作坊与合作社两种载体并行，前者保技艺纯度，后者保生产规模。",
  "history": "邦典织造以山南贡嘎县杰德秀镇为代表性产地，素有“邦典之乡”之称，其工艺与藏毯同属藏族毛织技艺体系。邦典共13道工序，一道都不能省，这13道工序同时也是氆氇的基本工序；最好的“斜玛”用14至20种染色毛纱精工织成，色条宽度与排列因地区和家族传统而异。2006年列入第一批国家级非遗。格桑为第一批国家级代表性传承人，创办杰德秀镇格桑围裙农民合作社；其女旦增卓嘎为全国劳动模范，已成为杰德秀邦典编织技艺的重要传承力量。",
  "meaning": "邦典是藏族已婚妇女的日常围裙，也是藏族毛织技艺体系中与藏毯并列的重要分支。它的文化意义在于：一件日常配饰同时承载了生态适应（羊毛的保暖性）、技术传统（细经粗纬的捻线逻辑）和身份标识（已婚妇女的穿着规制）三层功能。传承以家庭作坊和合作社为载体，格桑一代人的实践使邦典从“只挂在墙上”的展示品重新回到日常穿着。",
  "chain": "选羊毛→洗毛→晒毛→梳毛→捻线→上织机→织造→着色→反复浆染→揉搓→晾晒→缝合",
  "herFull": "国家级非遗；2006年第一批。",
