  "feature": "薯莨汁浸染加河泥媒染的两段式反应：薯莨单宁先层层渗入纤维，再以珠三角含矿河泥覆面，河泥中的高价铁离子与单宁反应生成黑色沉淀，绸面一面乌黑、一面棕红。完整工序近30道——浸莨水、晾晒、洒莨水、封莨水、煮练、过泥、水洗，其中浸、晒、洒、封、煮要反复二十余次。最苛刻的是过泥：河泥须过滤四五次，混沙即毁整匹；必须在夜间进行、天亮前完成，见日则底面也被染黑，双面效果全失。它不生产标准产品，每一匹都携带当日阳光、泥土与手法的印记，故有“软黄金”“黑色闪光珍珠”之称。",
