  "bio": "生于顺德伦教，1986年进入晒莨行业，在久和成晒莨场数十年如一日守全流程。行业最低谷时，顺德只剩一家晒莨厂，全厂一百多名工人走剩四人，连两万元流动资金都拿不出来；他坚持“什么活都接”，苦熬十年把场子保住。2025年获评第六批国家级代表性传承人。他的传承实践讲究“守魂跟潮”：守住过泥的夜间操作与河泥的纯净度，同时引入印花丝绸、缎、棉麻等新坯料，运用水洗、磨砂等现代后处理，并推动香云纱与宋锦两大国家级非遗的联合品牌。",
  "history": "香云纱染整技艺在顺德伦教等地传承数百年。1982年后，顺德仅存3家晒莨厂，不久后仅剩新民晒莨厂。最困难时，“全厂100多名工人只剩下4个人，连2万元的流动资金都拿不出来”。黄田胜1986年入行，在行业最低谷时坚持“什么活都接”以保住晒莨场，苦熬十年。2008年列入国家级非遗，2025年黄田胜获评第六批国家级代表性传承人。2011年顺德“香云纱”获国家地理标志产品认证。",
  "meaning": "香云纱的珍贵，在于它是一套完全被自然条件所规定的技艺：日照的强弱、河泥的矿物成分、薯莨汁的浓度、过泥的时辰，每一个变量都不可人为加速或替代。它生产的不是“标准产品”，而是每一匹都携带当日阳光、泥土与匠人手法印记的唯一物。黄田胜的传承实践具有标本意义：他在守住“魂”（过泥的夜间操作、河泥的纯净度）的同时跟上“潮”，引入印花丝绸、缎、棉麻等新坯料，运用水洗、磨砂等现代后处理，并推动香云纱与宋锦两大国家级非遗的联合品牌。这种“守魂跟潮”的分寸感，正是香云纱当代传承中最值得留意的经验。",
  "chain": "浸莨水→晾晒→洒莨水→封莨水→煮练→过泥→水洗，近30道完整工序",
  "herFull": "国家级非遗；2008年第二批；国家地理标志产品（2011）。",
