  "feature": "灰缬体系，靠浆料防染：以镂空花版覆布，刮涂黄豆粉与石灰调成的防染浆，干固后入靛蓝染缸，最后刮去灰浆显白花。九道工序——刻版、上铜油、湿布、和浆、刮浆、晾干、染色、晾晒、刮白，环环相扣。三处最吃分寸：刻线不宜过细过长，否则刮浆时损坏版片；浆的稠度须“黏稠适度”，稀则渗花、稠则堵版；刮浆要匀，浆层不均则花不齐。手工刮浆自然形成的冰裂纹——浆层在干燥与染色中细裂、染液渗入——是工业印染难以复刻的标识。纹样“有图必有意，有意必吉祥”，蓝白两色承担着民间吉祥、喜庆、健康的象征功能。",
