    "n": "和浆",
    "a": "石灰粉与黄豆粉按比例调和，加水搅成糊。比例随季节与布厚调整：天热易干，豆粉略增以保黏；布厚吃浆多，石灰略增以增硬。稠度要黏稠适度——太稀从版下渗开，花纹糊边；太稠刮不进镂空孔，白花残缺。调好的浆要静置一段时间让粉粒充分吸水，用前再搅一遍，手感如浓粥、挑起能挂住刮刀为宜。",
