    "n": "染色",
    "a": "入靛蓝染缸浸染。靛蓝不是直接上色，要靠还原态隐色体渗入纤维，取出后在空气中氧化才显蓝，所以是浸一次、提出透风氧化、再浸，如此反复。浸的次数决定深浅：浅蓝三四次，中蓝七八次，深蓝十余次，吴元新的复色工艺正是靠控制次数做出白与浅、中、深蓝的渐变。缸液温度、浓度、浸时都要守，出缸后不能马上水洗，要让氧化充分。",
