  "bio": "17岁进入民间印染作坊，师从印染师傅陆才涛、刻版师傅黄志平，从业四十余年。他收集散落民间的蓝印花布实物六万余件、纹样二十万余个，20世纪80年代中期发明复色印染技艺，创新多次套版刮浆印染技法，突破单调的蓝白两色，形成白色与浅蓝、中蓝、深蓝的渐变搭配。创办南通蓝印花布博物馆，形成“古旧收藏、技艺传承、艺术研究、院校教学、产品创新”五驾马车；2008年南通大学成立蓝印花布艺术研究所，2024年升格为研究院，出版专著十部，承担国家社科基金艺术学重点课题。",
  "history": "蓝印花布又称“药斑布”，其法可溯至唐宋，宋元以后随棉纺普及而兴盛，明清南通“家家纺纱、户户染布”，蓝印花布是被面、包袱布、帐檐的主料，曾“衣被天下”。20世纪中叶化学染料与机器印花兴起，民间染坊几近消失；九十年代起吴元新系统收集散落民间的实物与纹样。2006年列入首批国家级非遗，同年南通获评“中国蓝印花布之乡”，2013年获批国家地理标志产品。吴元新从业四十余年，20世纪80年代中期发明复色印染技艺。",
  "meaning": "蓝印花布的蓝白两色，在民间长期承担着吉祥、喜庆、健康的象征功能，是“衣被天下”的日常之物，而非观赏性的工艺摆设。吴元新的传承模式被概括为“五驾马车”：古旧收藏、技艺传承、艺术研究、院校教学、产品创新五位一体。他反复强调的一句话是“蓝印花布来自于生活，还必须要回到生活”。这种理念与那些将非遗“博物馆化”的路径形成对照：蓝印花布的技艺生命不在展柜里，而在刮浆刀与布面接触的那一瞬间。",
  "chain": "刻版→上铜油→湿布→和浆→刮浆→晾干→染色→晾晒→刮白，九道工序",
  "herFull": "国家级非遗；2006年第一批。",
