    "a": "浸染过程中，作为防染剂的蜡自然龟裂，染液从裂纹渗向织物，形成细如冰裂的蓝线。冰纹的走向与密度由三个变量决定：蜡层厚度、蜡液配方、浸染时的翻动方式。蜡厚则裂少纹粗，蜡薄则裂多纹细；掺松香多则脆易裂，掺牛油多则韧难裂。这一步不是人为画出来的，是蜡在染液中开裂留下的物性签名。",
    "t": "染缸",
    "h": "随浸染发生",
    "d": "中",
    "k": "冰纹不可复制，每一件的裂纹都不同，这正是手工蜡染的身份证明。",
