    "n": "脱蜡漂洗",
    "a": "染好的布入沸水煮，蜡受热熔化浮上水面，撇出回收，冷却后仍是黄蜡，可再用。煮到布面无蜡感、水不发黏为止。也可用热水反复洗。脱蜡后清水漂洗两三次，洗去浮色，晾干。蜡去则花现——被蜡盖住的部位仍是白地，与蓝底形成对比，冰纹同时显现。",
