  "bio": "苗族，1957年生，贵州安顺人。7岁开始学习蜡染，从点蜡、上色、封色、浸染到脱蜡漂洗，六十年来始终谨记“每一道工序都决定着作品的成败”。上世纪80年代应邀到各地表演，因作品极受欢迎被称为“蜡花小姐”，2018年获国家级代表性传承人称号。她在当地创办蜡染专业合作社，以合作社加社员模式带动四百余名社员；曾赴香港、台湾地区及法国、俄罗斯、印度等地展示苗族蜡染。近年尝试蜡染重彩画等新表达，作品融蜡染、绣染、扎染、刺绣、挑花、织锦于尺素。",
  "history": "丹寨苗族蜡染历史可溯至唐代；蜡染技艺列入国家级非遗。王月圆7岁开始学习蜡染，从点蜡到上色、封色、浸染、脱蜡漂洗，六十年来始终谨记“每一道工序都决定着作品的成败”。丹寨蜡染现有国家级传承人2名、省级2名、州级1名、县级41名，掌握技艺的苗族妇女1300余名。",
  "meaning": "蜡染图案分为几何纹与自然纹两大类，窝妥纹严谨对称，承载苗族族群记忆。冰纹的不可复制性，使每一件蜡染都是孤品——它不是对某个预设图案的精确执行，而是防染剂在染液中自然开裂后留下的“物性签名”。王月圆的传承实践兼具“守”与“创”：她坚守传统工序的每一个节点，同时尝试蜡染重彩画等新表达，作品融蜡染、绣染、扎染、刺绣、挑花、织锦于尺素。“以老带新”已培养百余名弟子，传承以家庭母女相传与工坊培训并行。",
  "chain": "布料处理→蜡液制作→蓝靛制作→点蜡（绘蜡）→浸染→脱蜡→漂洗",
  "herFull": "国家级非遗；苗族蜡染、安顺蜡染各有申报地区与保护单位。",
