    "a": "把版覆在白布上，用可洗的染料或蓝靛水把纹样印到布面，作为扎花的依据。印色要浅、要能洗掉，否则染后留下印痕。印的时候版要压紧，防止色浆渗到纹样外。印完晾干再扎，湿布扎时手滑，针脚不准。",
    "t": "印花版、染料",
