    "a": "拆好的布抖平，阴干或半阴半晒。暴晒会让蓝色发灰，阴干色更沉。晾时不要拧，拧出的折痕干了定型，很难熨平。干后低温熨烫，熨斗不压花心——花心是扎结处，纤维被压紧过，高温会留下亮痕。最后按纹样分等，针法复杂、白花清晰的为上。",
