  "bio": "白族，大理周城人，扎染世家出身，国家级代表性传承人，专精“扎”。她在30多种传统针法的基础上创新出100余种针法，其夫段树坤为省级代表性传承人，专注“染”。夫妇二人以扎染复刻宋代《张胜温画卷》中的《蛮王礼佛图》，代表白族扎染技艺的高度。周城扎染在她的带动下，已从民间作坊发展为亿元产业，家庭作坊、博物馆与高校教学并行——“扎”与“染”由两人分工专精，一管纹样的身体技艺，一管色彩的化学控制，两人配合本身就是一套完整的传承单元。",
  "history": "白族扎染距今已有上千年历史，被誉为“布上的青花瓷”。2006年列入第一批国家级非遗。段银开为国家级代表性传承人，专精“扎”；其夫段树坤为省级代表性传承人，专注“染”。夫妇二人以扎染复刻宋代《张胜温画卷》中的《蛮王礼佛图》，代表白族扎染技艺的高度。周城扎染已从民间作坊发展为亿元产业。",
  "meaning": "扎染的工艺逻辑是“以扎代笔”：不是用染料去“画”花，而是用线去“藏”花，染后拆线，被藏住的部分显白。针法的疏密、扎结的松紧、浸染的次数，共同决定最终纹样的面貌。这种“先藏后显”的逻辑，使扎染天然地带有一种不可完全预知的期待感——“到你拆了才知道”。段银开夫妇的传承模式值得注意：“扎”与“染”由两人分工专精，一人负责纹样的身体技艺，一人负责色彩的化学控制，夫妇二人的配合本身就是一套完整的传承单元。",
  "chain": "绘图→制版→印花→扎花→浸染→漂洗→拆花→晾晒",
  "herFull": "国家级非遗；2006年第一批。",
