  "bio": "王氏染坊第十代传人，温州首位蓝夹缬技艺国家级代表性传承人，2026年获评，时年70岁。精通靛青染料炼制与传统染色技艺，在中国丝绸博物馆专家指导下致力于重现彩色夹缬：投入五年、经历十四次失败才复刻成功，把对版误差控制在0.1毫米以内。创办温州市采成蓝夹缬博物馆（全国唯一兼顾制作与收藏的蓝夹缬民间博物馆），找回古法“打靛”，复原已失传百年的全版面图案，并在单一被面基础上开发五个系列；2026年收台湾弟子，推动蓝夹缬跨地域传播。",
  "history": "夹缬起于秦汉，盛于唐宋，元明后由彩色转单蓝，中原夹缬渐绝，仅浙南温州一带以单蓝双版延续，用于被面与嫁妆，故称蓝夹缬。温州至今完整保存雕版、制靛、印染全流程，被称为“雕版印染的活化石”与“四缬”之一。2011年列入第三批国家级非遗。王河生为温州首位蓝夹缬技艺国家级代表性传承人，创办采成蓝夹缬博物馆，复原古法打靛与失传百年的全版面图案，并在单一被面基础上开发五个系列。",
  "meaning": "蓝夹缬被称为“雕版印染的活化石”。它的技术逻辑与灰缬（蓝印花布）同属防染，但实现方式不同：灰缬靠浆料堵塞花纹，夹缬靠雕版夹紧布料、以沟槽引染。雕版本身是一件独立的雕刻艺术品，花版的“水路”设计既是技术，也是美学——纹样的精细程度直接受限于雕版刻线的宽度与深度。王河生的彩色夹缬复原，使一门长期局限于单色印染的技艺重新获得了多色表达的可能，其意义不在于“创新”，而在于恢复了夹缬在历史上曾经拥有的技术宽度。",
  "chain": "制靛→花版雕刻（画样、刻版、修版、水路设计）→布料夹持→印染固色→晾晒",
  "herFull": "国家级非遗；2011年第三批。",
