  "feature": "苏绣的技术骨架是三大谱系：平针绣讲“平、齐、细、密、匀、光、和、顺”，追求针脚的秩序；仿真绣（沈寿一脉）以光影写实为目标，讲究明暗过渡；乱针绣（杨守玉一脉）以交叉线条叠色，表现层次与质感。姚建萍在三者之上叠加韵光绣，用劈丝与捻线控制丝线反光，形成“融针绣”，做到“每针之间有疏密，每施一层有轻重转折”。劈丝是全部针法的前提：一根丝可分至极细，配色的层次直接决定光影过渡是否自然。因此苏绣的“工序”不是固定流水线，而是按题材调度针法的体系——同一幅绣面，衣纹求圆转、毛发要分层、光感靠叠色。",
