  "bio": "国家级代表性传承人，中国工艺美术大师，“姚派融针绣”创立者。以平针绣、仿真绣、乱针绣为根基，叠加自创的韵光绣，通过劈丝、捻线等绝技处理光影与肌理，形成“融针绣”，理念是“针融百家、因物运丝”。她突破传统苏绣题材多局限于小花小猫的局面，将油画、国画的线条与光影变化引入刺绣——一匹马的马头就要配四个色块。作品多次作为国礼。传承以大师工作室、院校教学与地方绣娘产业生态并行，把“针法调度”这门靠悟性的功夫拆成可教的模块。",
  "history": "苏绣以苏州为中心，宋代已有实物可证，明代受吴门画派影响形成“精细雅洁”的风格，清代苏州有“绣市”之称，出现专门行会与绣庄。清末沈寿创仿真绣，以光影写实入绣；民国王守玉创乱针绣，以交叉线条表现层次。二十世纪五十年代苏绣研究所成立。2006年列入第一批国家级非遗。姚建萍为国家级代表性传承人、中国工艺美术大师，作品多次作为国礼。",
  "meaning": "苏绣传统题材多局限于小花小猫，姚建萍将油画、国画的线条与光影变化引入刺绣，一匹马的马头就需要配四个色块。这种从“装饰性刺绣”向“绘画性刺绣”的推进，使苏绣的技术语言能够回应更复杂的视觉经验。苏绣的“工序”不是流水线，而是针法调度——同一幅绣面，衣纹求圆转、毛发要分层、光影靠叠色。针法谱系既是技术，也是师承的边界。传承以大师工作室、院校教学与地方绣娘产业生态并行。",
  "chain": "设计画稿→上绷→劈丝配色→依题材施针→落绷装裱",
  "herFull": "国家级非遗；2006年第一批。",
