  "feature": "以鬅毛针为标志：将丝线劈成粗细不等的缕，按毛发生长方向交叉施针，使绣出的毛发既有蓬松的体积感，又不至于板结成块——这是湘绣表现狮虎题材的独门绝技。湘绣共有70多种针法，人物用游针、掺针，光影用晕染，全异绣则两面成像、正反异色。针法体系的技术目标很明确：“绣花能生香，绣鸟能听声，绣虎能奔跑，绣人能传神”，讲的都是质感与动势的还原，而非轮廓的准确。狮虎题材承载湖湘审美中的雄健之气。",
