    "a": "湘绣七十多种针法，各有分工。狮虎用鬅毛针：丝线分缕、交叉运针，把劈好的丝缕按毛发生长方向斜向交叉，一层压一层，毛根处针脚密、毛尖处针脚疏，绣出的毛既有蓬松的体积感又不板结成块。人物用游针、掺针，游针线条流畅做轮廓，掺针做面色晕染。光影用晕染法，色与色之间不留硬边。江再红还把失传千年的汉代连珠针复原出来，用于表现颗粒状的肌理。",
