  "bio": "12岁拜师学绣，从事湘绣针法研究创作三十余年，第四批国家级代表性传承人，中国工艺美术大师。她不仅掌握湘绣独门的鬅毛针，还从汉墓出土文物中成功复原了失传千年的汉代连珠针，使断掉的技法重新进入当代湘绣的针法体系。江再红将掺针的晕染、鬅毛针的肌理、全异绣的奇幻有机融合，作品多次作为国礼。传承以大师工作室与校园教学并进。",
  "history": "湘绣形成于清末，以长沙为中心，吸收苏绣与粤绣之长而自成一系，与苏绣、蜀绣、粤绣并称四大名绣。20世纪上半叶湘绣行销海外，狮虎题材成为其标识。2006年列入第一批国家级非遗。江再红12岁拜师，为第四批国家级代表性传承人、中国工艺美术大师，从事湘绣针法研究创作三十余年，掌握鬅毛针，并从汉墓出土文物中复原了失传千年的汉代连珠针。",
  "meaning": "湘绣的狮虎题材承载湖湘审美中的雄健之气，“绣虎能奔跑”不是夸张，而是鬅毛针在毛发质感上的技术目标。江再红从汉墓出土文物中复制连珠针，其意义在于使失传技法重新进入当代湘绣的针法体系——传承不仅是向前看（培养新人），也是向后看（打捞断裂的传统）。湘绣共有70多种针法，掺针的晕染、鬅毛针的肌理、全异绣的奇幻常被并置于同一画面。",
  "chain": "画稿→上绷→配线→依题材施针→装裱",
