  "feature": "针法现有12大类、130多个品种，常用晕针、滚针、铺针、二三针、切针、沙针，是四大名绣中针法体系最庞大的一支，等于拥有一套可按物象质感自由调用的“针法词典”。晕针最独到：每排长短不等、针脚紧密相接，交错成水波纹，用以表现绣物的光、色、形；绣人物脸部若只用二三针排列会留下斜纹，无法表现面部肌理，因此层次过渡全靠晕针。整体风格施针严谨、线片光亮、针脚整齐、掺色柔和。晕针的水波纹逻辑，本质是用针脚排列模拟光线在曲面上的连续变化。",
