    "a": "蜀绣用色讲究柔和，同一色相要配出细密的阶差。晕针靠色阶的逐层推移表现光与形，阶差太粗就有明显的色带，太细又显不出层次，一般一个局部备五到七档。劈丝比苏绣略粗，蜀绣追求线片光亮，丝太细光泽就弱。配好的线按色阶顺序插在线的排架上，绣时按顺序取，不混。",
