    "n": "施针",
    "a": "蜀绣针法十二大类、一百三十多个品种。最独到的是晕针：每排针脚长短不等、紧密相接，排与排之间交错成水波纹，靠针脚的长短与排列密度表现绣物的光、色、形。绣人物脸部若只用二三针平排，会留下斜纹，表现不出面部肌理，必须用晕针做层次过渡。滚针做圆润的边线与筋络，一针接一针卷曲而行；铺针打底；沙针做颗粒；截针断色。芙蓉鲤鱼的鳞片要几种针法叠用，一片鳞往往换三次针。",
