  "bio": "1959年进入成都工艺美术技校蜀绣班，师从彭永兴，精通蜀绣100多种针法，第一批国家级代表性传承人，中国工艺美术大师。她尤擅人物刺绣，代表作《芙蓉鲤鱼》大量运用晕针表现质感，鲤鱼需用截、沙、浸、染等几十种针法配合完成。以大师工作室培养后继人才，其人物刺绣的针法体系是蜀绣传承中最具难度的部分之一。",
  "history": "蜀绣以成都为中心，晋代已有“蜀中之宝”之称，清代形成行业规模，与苏绣、湘绣、粤绣并称四大名绣。二十世纪五十年代后成都蜀绣厂成立，2006年列入第一批国家级非遗。郝淑萍1959年进入成都工艺美术技校蜀绣班，师从彭永兴，精通蜀绣100多种针法，为第一批国家级代表性传承人，尤擅人物刺绣；代表作《芙蓉鲤鱼》大量运用晕针表现质感。",
  "meaning": "蜀绣的针法体系在四大名绣中最为庞大，130多个品种意味着它拥有一套可以根据物象质感自由调用的“针法词典”。晕针的水波纹逻辑，本质上是用针脚的排列去模拟光线在曲面上的连续变化——这与西方绘画中的排线塑形在原理上相通，但材料是丝线，媒介是织物。郝淑萍以大师工作室培养后继人才，其人物刺绣的针法体系是蜀绣传承中最具难度的部分。",
  "chain": "选料→设计→勾稿→上绷→配线→刺绣→落绷→装裱",
  "herFull": "国家级非遗；2006年第一批。",
