  "feature": "广绣针法含钉、垫、拼、缀、铺五类，注重光影层次与丝理肌理；潮绣以金银线垫绣凸显立体质感，构图饱满、色彩富丽，装饰性极强。陈少芳的核心创新是“以画入绣”：先从“只打几个鳞片针机械地划分”发展到留水路的表现手法，再把颜色分为向阳与不向阳并设环境色，进而尝试“裸眼3D”的层次。她还创出一批专对性针法——绒毛针绣雏鸡、个字针绣小鹿和马、短发针绣小孩光头、竹编针绣竹篮，即按物象质感预先指定针法组合，而非套用固定程式。",
