    "a": "陈少芳一派的广绣不是看图绣花：从构思、绘图到针法编排，每一步都由主设计师亲身参与。构思阶段就要定这件作品用什么技术路线——是走传统金彩装饰，还是走以画入绣的光影路线；绘图时把物象拆成若干质感单元：羽毛、绒毛、鳞片、竹篾、皮肤，每个单元的质感对应一组针法。图上的高光与暗部要标出来，广绣的立体感靠留水路与环境色撑起来。",
