    "a": "陈氏广绣区别于一般广绣的核心环节：根据物象的质感预先设计针法组合，而不是套用固定程式。同样是鸟，雏鸡用绒毛针——针脚极短、层层叠压，做出绒的蓬松；小鹿与马用个字针——针脚排成“个”字形，模拟短毛的走向；小孩光头用短发针，一针一竖，短而挺；竹篮用竹编针，横竖交织如编篾。编排还要定留水路的位置：水路是色块之间留出的一线底料，靠它分隔形体、透出光感。",
