    "a": "按编排落针。广绣针法分钉、垫、拼、缀、铺五类，钉是钉线固定，垫是垫高做浮雕，拼是拼色拼料，缀是缀珠缀片，铺是平铺打底。绣制时先铺底、再垫高、后钉缀，层次由下往上。留水路要在落针时就留出来，不能绣完再刮——刮出来的水路边缘毛。潮绣的金银线垫绣则先用棉线垫出高度，再用金银线钉满，钉线的间距要匀，钉密了发死、钉疏了起泡。",
