  "bio": "第一批国家级粤绣（广绣）代表性传承人，中国工艺美术大师。她以画入绣，形成“陈式现代广绣”风格，并建立“丝线色彩构成法”。其创作不是“看图绣花”，而是从构思、绘图到针法编排都由主设计师亲身参与；历时十年创作长卷《岭南锦绣》，保存了广绣大部分针法与技巧。同项目国家级代表性传承人还有林智成、康惠芳、孙庆先等，康惠芳2015年获联合国“文化大使”称号。",
  "history": "粤绣包括广绣与潮绣两支，唐代已有记载，明清随广州口岸贸易兴盛，成为外销工艺品的大宗，构图饱满、色彩富丽、装饰性极强。广绣针法含钉、垫、拼、缀、铺五类，潮绣以金银线垫绣凸显立体质感。2006年粤绣（广绣）列入第一批国家级非遗，潮绣另有国家级非遗项目。陈少芳为第一批国家级代表性传承人、中国工艺美术大师，建立“丝线色彩构成法”，历时十年创作长卷《岭南锦绣》。",
  "meaning": "陈少芳的贡献在于将色彩构成原理系统引入广绣。传统广绣长于金彩和装饰性，但色彩关系多凭经验。陈少芳先熟悉广绣的“本体语言”——针法、过程、色彩关系，再实现传统与现代元素的融合。她从“只打几个鳞片针机械地划分”发展到留水路的表现手法，再把颜色分为向阳与不向阳并设环境色。传承以大师工作室、广绣行业与院校合作推进。",
  "chain": "构思→绘图→针法编排→落针绣图",
  "herFull": "国家级非遗（广绣）；2006年第一批。",
