    "n": "下针缝压",
    "a": "另一根针穿缝线。走针时，盘线绕着下针盘出细小的线圈，用左手大拇指尖立刻压住线圈，不让它回弹；右手把穿缝线的下针从圈中穿过，把圈缝实在布上。一压一穿一实，三个动作几乎同时完成，慢了圈就散。线圈的直径约两毫米，一圈挨一圈排列，像无数葡萄串铺在布上。层层压实是关键——压不实，线圈浮在布面，穿几次就磨断。",
