  "bio": "1959年生，13岁随母学绣，第一批国家级土族盘绣代表性传承人。她长期利用农闲组织刺绣爱好者传授技艺，把一门高度依赖身体记忆的针法在社区层面延续下来。传承实践同时包含守艺与拓品：将底料从传统棉布换成织锦，开发出抱枕、耳饰、香包、荷包、挂件等品类，“以前绣娘们是一件件卖，现在是网上一批批发货”。",
  "history": "盘绣流传于青海互助土族自治县一带，已有上千年历史，被称为指尖上的“彩虹”。土族无文字，纹样与针法全靠妇女之间口传心授，母女相传是主要路径。盘绣以黑色棉布为底，彩线至少十几个色级，成品上2毫米大小的圆圈均匀排列，如葡萄串一般。2006年入选首批国家级非遗。李发秀13岁随母学绣，为第一批国家级代表性传承人，利用农闲组织刺绣爱好者传授技艺。",
  "meaning": "盘绣的“两针两线”是一套高度身体化的双线协同技术：一根线负责“盘”出线圈，另一根线负责“缝”实固定，左手拇指充当临时“锚点”。这种操作无法被拆解为书面步骤，只能在长期的母女或师徒共处中被身体记住。李发秀的传承实践同时包含守艺与拓品：她将底料从传统棉布换成织锦，开发出抱枕、耳饰、香包、荷包、挂件等品类，“以前绣娘们是一件件卖，现在是网上一批批发货”。",
  "chain": "配线→上针盘线→下针缝压→依纹样连续盘缝",
  "herFull": "国家级非遗；2006年第一批。",
