  "feature": "世界上罕见的金属绣。将锡片剪成宽约1毫米、长约18厘米的细锡条，一头打一小勾，另一头剪成针头状，穿进深蓝底纹的棉线绣布，用锡条在棉线上打勾固定——锡条在这里既是线也是针，一穿一扣一剪，如同给经纬线系上一个银质的锚点。底纹用红、蓝、绿、黑丝线数纱绣，每一针须精确对应经纬线，多一针则纹乱、少一针则形散。以锡代银是材料替代的生存智慧：银料昂贵，锡色近银且不易氧化，于是长出一套独立的金属刺绣语言。图案的每个节点都被金属实体固定，织物因此带有其他绣种没有的硬质秩序感。",
