  "bio": "苗族，1963年生，5岁起随母学锡绣，8岁练习钩锡，15岁掌握全套技艺，第五批国家级苗绣（剑河苗绣）代表性传承人。其女陈艳辞去工作返乡传承，把锡绣融入耳环、吊坠、旗袍、西装和摆件；2024年苗族锡绣登上中国国际时装周，并随设计师合作登上巴黎时装周舞台。母女二人构成当代传承的核心链条。",
  "history": "锡绣仅存于贵州剑河县。苗族先民因银料昂贵，发现锡与银颜色相似且不易氧化生锈，便就地取材，用锡替代银，创造出金属刺绣工艺。2006年，以锡绣为代表的剑河苗绣列入国家级非遗代表性项目名录。龙女三九5岁起随母学锡绣，为第五批国家级代表性传承人。其女陈艳辞去工作返乡传承，将锡绣融入耳环、吊坠、旗袍、西装和摆件。2024年，苗族锡绣登上中国国际时装周，并随设计师合作登上巴黎时装周舞台。",
  "meaning": "锡绣的文化逻辑深植于材料替代的生存智慧：银是苗族最重要的身份与信仰材料，但银料昂贵，锡以相近的颜色和更好的抗腐蚀性成为替代品。这种“以锡代银”的选择，使锡绣在视觉上保持了银饰的金属光泽，在工艺上却发展出一套完全独立的金属刺绣语言。锡条的“锚点”逻辑——一穿一扣一剪——使图案的每一个节点都被金属实体固定，织物因此具有一种其他绣种不具备的硬质秩序感。传承上，龙女三九母女构成当代核心链条，陈艳的路径（文创产品+高定时装+国际舞台）为这门深山技艺打开了不依赖日常穿着场景的生存空间。",
  "chain": "纺线→织布→染色→绣底纹→铺花→补花→上锡→钩锡",
