  "feature": "九大工艺——镶、嵌、滚、宕、镂、雕、绣、盘、绘，本质是一套边缘处理与细节修辞：镶是加法，滚是收口，宕是镶边的变体，盘扣把功能件做成装饰。结构上承袭中式平面裁剪，又吸收西式开身、收腰，凸显体态曲线。合体不靠尺码，靠三件事：量体精确到36个部位、甚至40处；打省收束使平面衣片贴合曲面；归拔用熨斗与手劲把布推出胸腰曲线。手工缝纫坚持“一寸九针”，一件旗袍需四五十道工序，从选料、量体、裁剪、打省、上滚边到整烫，少则三天，多则数周。",
