    "n": "边缘工艺",
    "a": "镶、嵌、滚、宕四道边缘工艺，逐层处理衣缘、领口、开衩、袖口。镶是在边缘另镶一条异色或异料的边；嵌是在镶与面之间嵌一条细牙条，宽仅两三毫米，起分隔与提亮的作用；滚是用斜裁的滚条把毛边包住，滚条的宽窄要一致，斜裁的角度要对，否则弯处起皱；宕是在滚之外再宕一道花边或织带。四道可以单用，也可以叠用，叠用的层次顺序不能乱：先镶、再嵌、后滚、末宕。",
