  "bio": "1985年入上海龙凤中式服装店，拜归顺元为师，第四批国家级中式服装制作技艺代表性传承人。龙凤旗袍源于清乾隆末年专做中式服装的苏广成衣铺，1936年创立，自创立以来一直传承九大工艺，所有传承人都严格遵守。江满宗、张钦玮、吴雨婷等前后几代传承人多次带徒进社区、进学校开展非遗课程，2024年该技艺受邀参加法国里昂非遗展示。",
  "history": "旗袍由清代旗装演变而来，二十世纪二三十年代在上海完成现代定型，遂有京派、海派之分。龙凤旗袍源于苏广成衣铺，1936年创立，自创立以来一直传承九大工艺，所有传承人都严格遵守。2010年列入国家级非遗。徐永良1985年入上海龙凤中式服装店，拜归顺元为师，为第四批国家级代表性传承人。",
  "meaning": "36个部位的测量与一寸九针的密度，使“合体”在龙凤旗袍中不是尺码概念，而是一套以身体为尺度的精密工艺语言。九大工艺中，镶、嵌、滚、宕解决的是“边缘如何收束”，盘、绣、绘、镂、雕解决的是“表面如何装饰”，而打省与整烫解决的是“平面如何贴合曲面”。一件旗袍需四五十道工序，手工缝纫坚持“一寸九针”。传承以老字号工坊师徒制与院校合作并行。",
  "chain": "选料→量体（36部位）→试样→裁剪→打省→镶、嵌、滚、宕→盘扣、绣、绘、镂、雕→整烫",
  "herFull": "国家级非遗（中式服装制作技艺·龙凤旗袍手工制作技艺）；2010年第三批。",
