  "feature": "讲究“四功”（刀功、车功、手功、烫功），使成衣达到“九势”（胁势、胖势、窝势、戤势、凹势、翘势、剩势、圆势、弯势）与“十六个字”（平、服、顺、直、圆、登、挺、满、薄、松、匀、软、活、轻、窝、戤）。核心技术是推归拔：通过熨烫与手工推拉使衣片纤维塑性变形，热塑定型出符合人体曲面的立体形态——不是“缝”出来的造型，而是“烫”出来的造型。配套还有做衬（全毛衬纳针）、扎驳头、中间烫，全套工艺200多道。手工操作的立体造型能力，是机器至今无法替代的部分。",
