    "a": "奉帮用全毛衬，不用粘合衬。毛衬要按衣片形状逐片配，衬的厚度分区不同：胸衬厚、肩衬挺、驳头衬软。做衬是把衬与衣片用手针绷合，绷的针距要匀、线要松，不能把衬拉紧——衬拉紧了成衣就板。胸部还要加马尾衬或胸绒，做出饱满的胸型。做衬的手工量很大，一件上衣的衬要缝上万针。",
