    "a": "驳头是西装的脸面，扎驳头是奉帮的绝活。把驳头衬与面料用手针扎合，针脚藏在衬的一面，正面不见线迹。扎的时候要从驳头外缘向内扎，让驳头自然向里卷，卷的弧度要顺——太卷则驳头翻不平，太平则没有立体感。驳头的翘势靠扎的松紧控制，这是“九势”里的窝势与翘势。扎完烫定型，驳头要有弹性，按下去能回弹。",
