    "n": "中间烫",
    "a": "缝制过程中穿插的熨烫，不是最后整烫。每缝完一道缝、装完一个部件就烫一次，把缝份烫倒、把形体烫出来。中间烫要用整套烫具：烫凳、袖烫垫、肩烫垫、胸烫包，每个部位有专门的托具。烫的时候讲究“三分烫七分冷”，烫完不能马上动，要等冷却定型，动了就白烫。奉帮的“烫功”是四功之一，全在这一次次的中间烫里。",
