  "bio": "林瑞祥1946年入上海亨生西服店学徒，为第二代传人徐馀章开门弟子，改进并完善“十工头”工艺，开创“青年派”版型，第四批国家级代表性传承人，已故。肖文浩师从林瑞祥等，专注奉帮技艺四十余年，为上海市级传承人，全部掌握亨生传统工艺。为避免师徒口传心授导致技艺流失，《亨生奉帮裁缝制作技艺》一书把“四功”“九势”“十六字”整理成可检验的标准。",
  "history": "亨生由奉帮裁缝徐继生1929年创立，为奉帮西式服装的代表。林瑞祥1946年入上海亨生西服店学徒，为第二代传人徐馀章开门弟子，第四批国家级代表性传承人。为避免传统师徒口传心授方式导致的手工技艺流失风险，《亨生奉帮裁缝制作技艺》一书将“四功”“九势”“十六字”的制作工艺标准进行系统整理。",
  "meaning": "“四功九势十六字”的本质，是一套将身体曲面翻译为织物形态的技术语言。推归拔不是“把布烫平”，而是“把布烫成身体需要的形状”；九势中的“窝势”“戤势”“胖势”等，每一个字都对应人体某一部位在穿着状态下需要的立体趋向。林瑞祥已故，肖文浩一代承担的任务，是把这套高度个人化的手感经验转化为可教学、可检验的文本标准。全套工艺约200多道步骤。",
  "chain": "量体→打版→裁剪→推归拔→做衬→扎驳头→中间烫→试样→整烫",
  "herFull": "国家级非遗（中式服装制作技艺·亨生奉帮裁缝技艺）；第四批。",
  "inheritor": [
   {
    "name": "林瑞祥",
    "role": "第四批国家级代表性传承人（已故）"
   },
   {
    "name": "肖文浩",
    "role": "上海市级传承人"
   }
  ],
  "video": "上海地方媒体“九旬老字号亨生”专题；《亨生奉帮裁缝制作技艺》发布影像。",
