    "d": "林瑞祥为第四批国家级代表性传承人；肖文浩为上海市级传承人，师从林瑞祥等，专注奉帮技艺四十余年。",
    "h": "推归拔：奉帮的核心不是“缝”，是用熨烫和手工推拉让织物发生塑性变形，造型是“烫”出来的。九势是一套用汉字命名的身体—织物关系词典。"
