  "peak": "极高",
  "feature": "纺、染、织、绣四大工艺的完整体系，一个人可以从纤维做到成衣。絣染最难也最耗时：与常见的先织后染相反，絣染先染后织——把理好的白棉线套在木架上作经线，分成若干股，用青色棉线在每股白线上绕圈扎结，一个结一个结地扎出花纹，然后入蓝靛浸染，解结后整经上机，用踞腰织机织造。做图不需描样，图案熟稔于心，这意味着传承传递的不是一张图纸，而是一整套内化于身体的空间秩序。龙被集纺、染、织、绣于一体，由单幅或多幅黎锦连缀而成，是黎锦技艺的巅峰。染料多取山区野生或家种植物，色彩鲜艳、不易褪色。",
