    "n": "浸染",
    "a": "扎好的经线入蓝靛缸浸染。染液要渗进扎结之间的空隙，扎结处进不去，解结后即为白花。浸染反复多次，每浸一次提出氧化，由黄绿转蓝才算氧化足。浸的时候要轻，不能揉搓扎结，搓松了就渗蓝。染够次数后晾干，再解结。黎族用山区野生或家种的植物染料，色牢度好，不易褪色。",
    "t": "染缸、蓝靛、黄姜",
