    "a": "踞腰织机一头系在腰上，一头用脚踏住经轴，靠身体的仰俯控制经线张力。织的时候腰往后仰则经线张紧、开口清晰，往前俯则松。投梭引纬、打纬用木刀或筘，打纬的力要匀。黎锦的图案没有现成稿样，全凭织者记忆与经验，一边织一边在脑中比对纹样。双面绣与单面提花也在这一步完成。",
