    "a": "龙被是黎锦的巅峰，集纺、染、织、绣四大工艺于一身，由单幅或多幅黎锦连缀而成。连缀时要把几幅的纹样对齐——龙被的图案横跨数幅，错半条整幅龙身就断。缝线要细、针脚要藏，正面不见接缝。有的龙被还要在连缀后加绣，用双面绣补纹样。符庆香选用人工种植的海岛棉白色经线、以自采的黄姜染色，花一年半才织成一条絣染龙被。",
