  "feature": "整套技艺包含织布、绘图、染色、绣饰四大环节，核心是妇女的纺纱织布、蜡染、挑花刺绣。技术特点在“闭环”：一件盛装由同一双手从纱线做到成衣，纹样、色彩与形制彼此对应，不依赖分工协作。蜡染以蜡刀点画、蓝靛浸染，冰纹决定肌理；挑花以数纱定位、十字交叉成型，不打底稿、双面成纹。因苗族无本民族文字，迁徙路线、族群记忆与信仰被绣入衣冠，不同支系的形制、纹样、色彩差异显著，服饰因此成为可识别的族属标识，被称为“穿在身上的史书”。",
