    "n": "绣饰",
    "a": "苗族服饰的绣饰是重头，不同支系各擅其法：有的挑花，数纱而绣、不打底稿；有的蜡染后再绣；有的贴布堆绣。绣的部位集中在衣襟、袖口、背肩、裙腰——这些是磨损最重的地方，绣饰兼有装饰与加固的双重作用。用色浓烈，红、黄、绿、蓝对比强烈，一件盛装往往要绣数月乃至一年。绣的密度要达到针脚覆盖底布，看不见布纹。",
