  "bio": "1967年生，贵州六枝人，第五批国家级苗族服饰代表性传承人。六七岁随母学蜡染和刺绣，10岁初步掌握服饰制作，十三四岁学织布，十五六岁开始制作完整苗族服饰——这条时间线本身说明，这套知识不是课程，而是成年礼的一部分。她所在的支系至今保持从纺纱到成衣全程自制的习惯，一件盛装从纱线到银饰配齐往往跨年。",
  "history": "苗族服饰2006年列入第一批国家级非遗。苗族没有本民族文字，迁徙路线、族群记忆与信仰被绣入衣冠，服饰因此被称为“穿在身上的史书”。不同支系在形制、纹样、色彩上差异显著，同一件盛装往往集织布、蜡染、挑花、刺绣于一身。熊光珍为第五批国家级苗族服饰代表性传承人，六七岁随母学蜡染和刺绣，10岁初步掌握服饰制作，十三四岁学织布，十五六岁开始制作完整苗族服饰。",
  "meaning": "苗族服饰的价值不在单件工艺，而在“织—染—绣—缝”的完整闭环：一件盛装由同一双手从纱线做到成衣，纹样、色彩与形制彼此对应。因无文字，迁徙路线与族群记忆被绣入衣冠，服饰被称为“穿在身上的史书”。熊光珍的成长路径说明这套知识有严格的时间表——它不是课程，是成年礼的一部分。",
  "chain": "纺纱织布→绘图→染色（蜡染）→绣饰→裁剪缝制",
