  "peak": "极高",
  "feature": "扎扎服饰流传于山南措美县哲古一带，属藏族服饰的地方类型：长袖、右衽、束腰，以氆氇与毛皮为材，农区与牧区形制差异明显。最鲜明的识别特征是“反穿花氆氇”——毛面朝外、花纹在内，既挡风雪又耐磨，花纹贴身兼顾体面。工艺从纺线、织布、染色到缝制，十多道工序，耗费近两个月才能完成一套，面料本身即最难以替代的部分。藏族服饰多个支系分别列入国家级非遗，普兰“宣”服饰2008年列入第二批。",
