    "n": "配饰搭配",
    "a": "藏族服饰的完整形制包括头饰、项饰、腰带、靴子。配饰不是附加，而是身份与地域的标识：卫藏、康区、安多的头饰形制差别极大，牧区与农区也不同。佩戴时腰带要系在腰节偏上，袍身下摆提到膝上，形成藏族特有的前襟垂袋。配饰的重量与位置会影响袍身的垂坠，穿戴顺序是袍、带、饰、帽。",
