  "bio": "1970年10月生，西藏措美县人，国家级藏族扎扎服饰代表性传承人。14岁随父亲学习扎扎服饰裁缝技艺，掌握氆氇编织、染配色、缝制等全工序。与妻子白玛德吉积极收徒授艺，目前已有15名传习人。他把传统两件套改良为一件大斜襟自带腰带，以适应现代穿着习惯。旦增多杰为第四批国家级藏族服饰代表性传承人。",
  "history": "藏族服饰2008年列入第二批国家级非遗，多个支系分别列项，普兰“宣”服饰2008年列入第二批。扎扎服饰流传于山南措美县哲古一带，农区与牧区形制差异明显，长袖、右衽、束腰，以氆氇与毛皮为材，反穿花氆氇是其标志。阿旺旦达14岁开始学习，掌握氆氇编织、染配色、缝制全工序，为国家级代表性传承人，现有传习人十五名。",
  "meaning": "服饰与高原环境、生产方式深度绑定，扎扎服饰是吐蕃与唐文化交流的产物。阿旺旦达把传统两件套改良为一件大斜襟自带腰带，以适应现代穿着——核心不变、外围可变，是民族服饰活态传承的通行策略。一套服饰从纺线到缝制要十多道工序、耗费近两个月，面料本身即最难以替代的部分。",
  "chain": "纺线→织布→染色→缝制→配饰",
  "herFull": "国家级非遗；第五批传承人。",
