    "a": "领口、袖口、襟边绣花。蒙古族刺绣的技法包括绣、贴、堆、剁：绣是平绣，贴是贴布绣，堆是堆绫（把绫子叠成花瓣堆缝），剁是用针把线剁进面料形成绒面。软面料上用丝线绣，硬面料（羊毛毡、皮靴）上用驼绒线、牛筋线绣，针要粗、孔要大。纹样多为云纹、卷草、犄纹、盘肠，色彩浓烈，红蓝黄为主。绣的部位也是磨损最重的地方，绣饰兼加固。",
