  "bio": "其木格，第五批国家级蒙古族服饰代表性传承人，退休后创办正蓝旗蒙元吉颂民族服饰服装店，专做察哈尔部落传统服饰并收徒传艺，形成独特的察哈尔服饰体系。斯庆巴拉木（斯琴巴拉木），1941年1月生，鄂尔多斯乌审旗人，第四批国家级传承人：8岁随母亲布勒特格尔学习裁剪、纳缝、绣花及男士配饰、妇女首饰制作，家传技艺第三代传人，1978年起全力投入鄂尔多斯蒙古族服饰的研究与制作，成立家庭作坊；妹妹仁庆苏布德、浪腾苏布德均为自治区级传承人，姐妹三人被拍成纪录片《三姐妹》。",
  "history": "蒙古族服饰2008年列入国家级非遗，2014年扩展，2021年公布为第五批国家级非遗代表性项目。其木格为第五批国家级传承人，退休后创办正蓝旗蒙元吉颂民族服饰服装店，制作察哈尔部落传统服饰并收徒传艺；斯庆巴拉木为第四批国家级传承人，8岁随母学习裁剪、纳缝、绣花及首饰制作。",
  "meaning": "每一细节和工艺背后都有游牧文化的象征意义。蒙古族服饰集裁剪缝纫、贵金属加工、饰品制作于一体，刺绣可在软面料上绣花，也用驼绒线、牛筋在羊毛毡、皮靴等硬面料上刺绣，技法包括绣、贴、堆、剁等。保护难点在整体性：袍子可以收藏，穿着场景与部族知识却难以保存。其木格以察哈尔体系立店授徒，斯庆巴拉木以家族传承，一为“体系化”，一为“家族化”。",
  "chain": "裁剪→纳缝→绣花（软料/硬料）→配饰制作→整体搭配",
  "herFull": "国家级非遗；第四批、第五批传承人。",
