  "bio": "1955年3月生，吉林延吉人，第五批国家级朝鲜族服饰代表性传承人。自幼随母亲姜善玉学习传统服饰制作和刺绣工艺，1980年创办服装店，从事民族服装事业四十余年。她注重总结服饰的精神内涵并传授给徒弟，先后培养出二十多名学徒，并确定了家族第四代和第五代传承人；同时常到社区和村落向老艺人学习，搜集民族节庆礼仪素材用于服饰制作。",
  "history": "朝鲜族服饰随朝鲜半岛移民在十九世纪中后期大量传入延边地区，逐渐形成中国朝鲜族的服饰传统。女装短衣（赤古里）长裙（契玛），斜襟无纽扣、以长布带打结；男装短上衣配宽腿裤，颜色以白色为主，故有“白衣民族”之称。2008年列入第二批国家级非遗，延边现有国家级、省级、州级传承人四代。俞玉兰为第五批国家级代表性传承人，已培养二十多名学徒并确定家族第四、五代传承人。",
  "meaning": "朝鲜族服饰的美学在留白：短衣只及胸下，长裙高束于胸，比例上把视觉重心抬高；斜襟与长布带取代纽扣，把“系”的动作仪式化。采用平面裁剪法，将直线与曲线结合，从设计到成服的几十道工序全部手工完成。俞玉兰强调精神内涵的传授，正因这类服饰的难点不在裁剪，而在何时穿、怎么穿、配什么礼——剥离场景，衣服就只剩布料。",
  "chain": "面料处理→设计→裁剪→缝制→配饰与穿着礼仪",
  "herFull": "国家级非遗；2008年第二批。",
