  "bio": "兰曲钗，第五批国家级畲族服饰代表性传承人，13岁随父学艺，制作畲服四十余年，在修边、纳沿、手工刺绣方面有创新。其子兰银才为福建省级代表性传承人、畲服技艺第五代守艺人，承袭家传手艺，深耕凤凰装制作，熟练掌握裁剪、车花边等全套工序，并走进当地小学校园开展非遗课堂。林章明为闽东畲族传统服饰制作技艺代表性传承人，以《闽东畲族凤凰装文化渊源与类别辨析》为题走进高校。",
  "history": "畲族服饰列入国家级非遗，闽东、罗源等地各有传承脉络。畲族将女性视作凤凰的化身，女性传统服饰以凤凰图案贯穿整体，头饰呈现凤凰轮廓，俗称凤凰装；一套凤凰装由头饰、衣服、蚕丝带、花带、围兜、绑裙组成，不同聚居地的细节存在地方差异。兰曲钗为第五批国家级畲族服饰代表性传承人，13岁随父学艺，制作畲服四十余年；其子兰银才为第五代守艺人。",
  "meaning": "畲族将女性视为凤凰化身，凤凰装承载吉祥寓意与祖先怀念。数十条红、白两色捆扎条层层叠叠缝订在衣身，模拟凤凰羽翼斑斓错落的效果。它是一套成套的识别系统：头饰、衣身、蚕丝带、花带、围兜、绑裙缺一不可。兰曲钗在修边、纳沿、手工刺绣方面有创新，说明传统形制并非不能动——动在细节，不动在识别。",
