    "a": "布依族尚青蓝，蓝靛染是主色。靛蓝靠还原态隐色体渗入纤维，取出氧化显蓝，所以要反复浸、提、氧化。染的次数决定深浅，日常装浅、盛装深。染时加酒或草木灰水助染。染完漂洗、晾干、捶布，捶出蓝光。布依族的蓝靛染讲究色沉而不浮，穿久了会有一种沉静的光。",
