    "n": "挑花刺绣",
    "a": "布依族的挑花与刺绣多用在衣襟、袖口、围腰、背扇上。挑花数纱而绣，不打底稿，按布的经纬格数下针，图案多为蝴蝶纹、蕨菜纹、铜鼓纹——每一种纹样都有文化寓意，王菁在传授时会把纹样的来历一并讲清。刺绣的针法有平绣、锁绣、辫绣等。用色以蓝、青为底，红、黄、绿点缀，浓淡相衬。",
