  "bio": "1971年生，贵州兴义人，第五批国家级布依族服饰代表性传承人。10岁起随奶奶和妈妈学习纺纱、织布、蜡染、裁剪。她建立布依族服饰博物馆，培训超万人，并通过传统“拜师礼”与现代培养机制结合的方式，系统传授“蝴蝶纹”“蕨菜纹”“铜鼓纹”等纹样的文化寓意与绣制技法；同时以“传统元素+时尚”带动绣娘就业。",
  "history": "布依族聚居黔西南与黔南，服饰尚青蓝，以蓝靛染布为基调，兼用蜡染与扎染，一套服装要经过纺纱、织布、蜡染、扎染、挑花、裁剪、刺绣等数十道工序，短则几天，长则几个月。布依族服饰列入国家级非遗。王菁为第五批国家级代表性传承人，10岁起随奶奶和妈妈学习纺纱、织布、蜡染、裁剪，建立布依族服饰博物馆，培训超万人。",
  "meaning": "一套服装要经过纺纱、织布、蜡染、扎染、挑花、裁剪、刺绣等数十道工序，短则几天，长则几个月。王菁建立布依族服饰博物馆，培训超万人，并通过传统“拜师礼”与现代培养机制结合的方式，系统传授“蝴蝶纹”“蕨菜纹”“铜鼓纹”等纹样的文化寓意与绣制技法——纹样先有意义，后有针法，这个顺序不能倒。",
  "chain": "纺纱→织布→蜡染/扎染→挑花→裁剪→刺绣→缝合",
  "herFull": "国家级非遗；第五批代表性传承人。",
