    "a": "把鞣好的鱼皮切成两三毫米宽的细条，搓成线——缝衣的线也是鱼皮做的。搓线要顺着皮纤维的方向，搓得太紧会断，太松会散。鱼皮线比棉线硬、比麻线滑，缝的时候针脚要密，否则线会退出来；缝口最后涂一层鱼鳔胶封孔，防水。",
