    "n": "缝制成衣",
    "a": "用鱼皮线、鱼骨针、鱼鳔胶缝制。鱼皮线也是鱼皮做的：把鱼皮切去四角不整齐处，抹一层狗鱼油，待皮潮湿后卷起，用小木板紧紧捺住，用快刀切成细线，线的一头要细一些以便穿针。缝的时候先用鱼骨针穿孔，针脚要密，缝完在缝口涂鱼鳔胶封住针孔——鱼皮衣靠胶封防水。鱼皮按颜色深浅、鳞纹大小筛选后拼接成大块面料，再裁剪、定型、装饰。一件鱼皮衣需两个月、数十条鱼皮，仅缝制环节三人就用了十二天。",
