  "bio": "黑龙江同江街津口乡渔业村人，第一批国家级赫哲族鱼皮制作技艺代表性传承人。15岁随母尤翠玉学艺——母亲曾是赫哲族聚居地唯一会制作鱼皮衣的人，母亲去世后她继承了这门手艺，能独立完成从剥皮到成品的全过程。她的收徒方式近乎严苛：来学的人不收一分钱，先学鞣制鱼皮，能坚持下来再继续教。鞣皮是整条链上最苦、最累、最不“好看”的环节，能过这一关的人才谈得上传承。",
  "history": "赫哲族世居黑龙江、松花江、乌苏里江汇流地带，以渔猎为生，鱼皮衣是这一生计方式的直接产物。鱼皮衣制作技艺已传承上千年，2006年列入首批国家级非遗。20世纪中叶以后，随着渔猎生计转型与棉布普及，技艺一度濒临失传，掌握完整工序者极少。尤文凤为第一批国家级代表性传承人，其母尤翠玉曾是赫哲族聚居地唯一会制作鱼皮衣的人，母亲去世后她继承了这门手艺。",
  "meaning": "鱼皮衣的每一步都是对特定物性的精确回应：玉米面七次去腥利用的是玉米面吸附油脂与腥味物质的物理特性，木铡刀反复铡压使胶原纤维松弛而获得柔软度，鱼皮线以鱼肝油润湿保证缝合时的韧性与顺滑。尤文凤的传承方式带有一种近乎严苛的筛选逻辑：每一个来学的人她都不收一分钱，先让他们学鞣制鱼皮，能坚持下来，再继续教。鞣皮是整条工艺链中最苦、最累、最不“好看”的环节，能过这一关的人，才谈得上传承。",
  "chain": "剥皮→干燥→鞣制去腥→缝制成衣",
  "herFull": "国家级非遗；2006年第一批。",
