  "feature": "整合考古学、皮革皮艺、织造、绳结编织、传统漆艺、人体工程等多学科知识。形制包括铁札甲、鱼鳞甲、布面甲：札甲竖向排列、穿孔编缀、层层覆盖，鱼鳞甲叠压如鳞。工艺有锤、蹀、冲、折、裁、焊、墩、拔等，冷锻造不用火，全凭手劲与巧劲，每片甲片捶打3000多次才成型，厚度仅0.3毫米；部分甲胄还需淬火与热处理。复原一套精致铠甲需八大工序、十六项程序，耗时约三个月。甲片的弯度、孔位与编缀方式，同时是防护功能、身体活动需求与时代工艺水平的交汇点。",
