  "bio": "1994年生，川派铁作盔铠技艺传承人，“玉衡司”甲胄工作室负责人。大学时因同学一句“中国的盔甲在哪里”而下定决心复原中国铠甲，2015年到射洪，2019年成立工作室。该技艺目前主要依托民间制甲者与爱好者群体存续，尚未形成国家级非遗名录体系下的传承人序列，团队以影视道具与博物馆复原维持生存。工作室取名“玉衡司”，取北斗七星中玉衡星位处文曲与武曲之间的意象——“武”是铠甲制作，“文”是服饰礼仪与形制考据。",
  "history": "战国曾侯乙墓皮甲实物显示甲身、甲袖、甲裙共164块甲片，全部髹漆；铁甲时代札甲与鱼鳞甲为主流。成曦1994年生，川派铁作盔铠技艺传承人，“玉衡司”甲胄工作室负责人。他大学时因同学一句“中国的盔甲在哪里”而下定决心复原中国铠甲，2015年到射洪，2019年成立工作室。该技艺目前主要依托民间制甲者与爱好者群体存续，尚未形成国家级非遗名录体系下的传承人序列。",
  "meaning": "甲胄复原的意义超出“做一件衣服”，它接近于以物质手段复现古代军事身体的构造方式。甲片的弯度、孔位、编缀方式，每一个细节都同时是防护功能、身体活动需求和时代工艺水平的交汇点。中国历代严禁私人制作和收藏甲胄，几乎没有完整的古代铠甲实物留存，资料散落在兵书文献、壁画石刻与帝王陵墓石像中。成曦为工作室取名“玉衡司”，取北斗七星中玉衡星位处文曲与武曲之间的意象——“武”是铠甲制作，“文”是服饰礼仪与形制考据。传承面临断层，年轻制甲者的实践在名录体系之外保留了活态空间。",
  "chain": "考证→选材→冶炼→锻打→制版→塑型→编札/铆接→錾刻→铸造→缝合",
  "herFull": "地方非遗层级（川派铁作盔铠等），尚无统一的“传统甲胄制作技艺”国家级项目。",
