  "feature": "戏衣制作融画、绣、制衣于一体，一件需20多道至30多道工序，从头到尾经裁剪、绷片儿、配线等环节，不可能一个人完成；染色配方与刺绣针法长期以家传方式封闭传承。另一半知识是衣箱制：大衣箱管文服（蟒袍、帔、褶子、官衣、八卦衣、开氅、宫装、坎肩、斗篷、青衣，兼管玉带、朝珠、扇子、牙笏），二衣箱管武服（靠、打衣、箭衣、龙套衣、马褂），三衣箱管靴鞋、内衣、水衣、胖袄、护领、彩裤、打鞋，另有盔箱、旗包箱、把箱。穿戴遵循“宁穿破，不穿错”，按角色行当而非朝代定服饰。",
