    "n": "配套归类",
    "a": "戏衣做好要入衣箱，衣箱管理本身是一门知识。大衣箱管文服：蟒袍、帔、褶子、官衣、八卦衣、开氅、宫装、坎肩、斗篷、青衣，兼管玉带、朝珠、扇子、牙笏、手帕、腰巾；二衣箱管武服：靠、打衣、箭衣、龙套衣、马褂；三衣箱管靴鞋、内衣、水衣、胖袄、护领、彩裤、打鞋；另有盔箱、旗包箱、把箱。大衣箱师傅必须熟知剧目、剧情、角色家门、扮相、扎扮规制、锣鼓经以及每出戏的演出时间。",
