  "bio": "孙颖，1957年生，第三批国家级非物质文化遗产项目剧装戏具制作技艺代表性传承人。在北京工艺美术技校学习京绣，1976年入北京剧装厂，师承尹元贞、王敏政学习传统戏装设计。她既做戏衣，也懂衣箱规制：知道哪出戏、哪个角色、在哪个情境下穿哪一件。这种“会读戏”的能力，使“做戏衣”与“管衣箱”两套知识在她身上没有断档。",
  "history": "戏衣业原附属于刺绣行业，清代从刺绣中独立出来，苏州为重要发源地，北京、上海随后形成剧装作坊群。昆曲衣箱在长期演出实践中形成严密的穿戴规制，大衣箱、二衣箱、三衣箱分箱管理，另有盔箱、旗包箱、把箱。孙颖为第三批国家级非物质文化遗产项目剧装戏具制作技艺代表性传承人，1957年生，在北京工艺美术技校学习京绣，1976年入北京剧装厂，师承尹元贞、王敏政学习传统戏装设计。",
  "meaning": "戏衣服务的是舞台程式而非日常身体。一套行头的规制本身是浓缩的舞台制度史：大衣箱师傅的知识不是“会做衣服”，而是会读戏——知道哪出戏、哪个角色、在哪个情境下穿哪一件，穿错一件就是穿错一套意义系统。穿戴遵循“宁穿破，不穿错”，按角色行当而非朝代定服饰。衣箱管理长期靠老师傅口传身授，专业人才缺口是突出问题。孙颖一代的技艺传习，使“做戏衣”与“管衣箱”这两套知识不至于同时断档。",
  "chain": "设计→画样→刺绣→裁剪→缝制→归拔定型→盔头/靴鞋配套→衣箱归类管理",
  "herFull": "国家级非遗（剧装戏具制作技艺）；孙颖为第三批代表性传承人。",
