    "n": "整理",
    "a": "下机后验布：看纬密是否匀、彩锦的色块边界是否齐、有无跳梭与稀弄。壮锦的稀弄多出现在换梭处，换梭不紧就留一道缝。验完修去背面浮线，剪线头要贴根剪，不伤经线。然后熨平、卷匹。李村灵把传统六十厘米的宽幅改良为一百二十厘米，减少拼接、提升整体性，整理时也要按新幅宽验。",
