  "bio": "李村灵，1967年4月生，第五批国家级代表性传承人，靖西壮锦厂厂长。1987年20岁进厂，本职财务，下班后上机实操，小半年掌握绘图、纺纱、染色、编织全套技艺，练就“稿图在心中”的本领。她把传统60厘米幅宽织机改良为120厘米，减少拼接、提升整体性；推动壮锦进校园，从幼儿园到初中开设“壮锦小课堂”，并与高校合作在厂房内开设研学实践工作坊。靖西壮锦厂入选第一批国家级非遗生产性保护示范基地。",
  "history": "壮族先民汉代织出的“斑布”即壮锦前身，唐宋已见“緂布”类织物，明清进一步发展，明代列为贡品，清代桂西一带嫁奁必备壮锦。壮语称“天纹之页”，手工织造史约一千五百年。二十世纪中期各地壮锦厂成立，家庭织造转为集体生产；2006年列入第一批国家级非遗，靖西壮锦厂入选第一批国家级非遗生产性保护示范基地。",
  "meaning": "壮锦的骨架是通经通纬与通经断纬并用：素色地子用通纬快织，彩锦段落改断纬换色，效率与色彩在一匹布上分工。纹样多为菱形骨架内填万字、水波、鸟兽，是稻作文明的视觉语法。李村灵把六十厘米幅宽改成一百二十厘米，看似只是机械改良，实则回应了成品拼接过多、整体性不足的痛点——技艺的现代化，往往从工具尺度开始。传承走“工厂—校园—高校研学”三层：工厂保生产，校园保兴趣，研学保研究，缺一层都会断层。",
  "chain": "牵经→装造→挑花结本→上机→通经断纬或通经通纬织造。",
  "herFull": "第一批国家级非遗（2006），申报地区广西壮族自治区靖西市等。",
