  "bio": "宋树牙（1945—2025），第三批国家级代表性传承人，江西万载人，出身夏布织造世家，自祖父起家族五代专职从事夏布生产经营。1998年创办万载县双志夏布厂，产品销往国外。其子宋志学承袭技艺30余年，将云南扎染引入夏布工艺品，设计鞋包、帽子、折扇、茶席等200余种文创产品；2023年父子打造的夏布文化馆开馆，设织造体验区。",
  "history": "苎麻织造可上溯至新石器时代，商周已有“纻衣”，唐宋列为贡品。江西万载、重庆荣昌因水质与气候适宜漂麻而成为主产区，明代万载夏布行销江南，清末民初经广州、汉口出口朝鲜、日本与南洋。抗战后洋布冲击，作坊大量停业；2008年万载夏布、荣昌夏布以“夏布织造技艺”列入第二批国家级非遗。近年以文创产品与出口日本和服面料为主要去向。",
  "meaning": "夏布的价值全在慢工：绩纱要把麻条撕成细缕、首尾捻接，接成一根不断头的长线，一匹布的用纱一个人要绩近两个月——这道工序没有捷径，也无法外包给机器。“平如水镜，轻如罗绡”说的是成品，成本却压在前端。历史上夏布兼具庶民衣料与贡品双重身份，今天其透气、吸汗、抑菌的物理性能重新被市场需要。宋志学的路径是“保留手工、扩展场景”：工艺上与高校合作优化流程，产品上做鞋包、折扇、茶席两百余种——先让人用起来，技艺才有活路。",
  "chain": "苎麻处理（浸水软化、去杂质、晨露漂白、干燥）→绩纱→挽团→整经→过筘→上浆→穿综→织布→晾晒。“过筘”增加边缘强度，“上浆”使纱线不起毛、不断线。",
  "herFull": "第二批国家级非遗（2008），编号Ⅷ-102，申报地区江西省万载县、重庆市荣昌区。",
