  "bio": "王启萍，1950年8月生，贵阳花溪人，第五批国家级代表性传承人。7岁随母亲及长辈学绣，12岁掌握基本技艺，后拜王朝珍为师学习传统苗族挑花绣。从事花溪苗绣六十余年，掌握十字针、鱼骨针、鱼刺针、豆花针等十余种针法，开班授徒，培养学生四十余人、徒弟十余人。2021年被推选为中国纺织·非遗苗绣推广大使，获“薪传奖”。代表作有《苗族妇女盛装》《苗姑》《娃娃肚兜》及四喜冰花纹背扇等。",
  "history": "花溪苗绣属苗族挑花一支，流传于贵阳花溪一带的苗族村寨。苗族没有本民族文字，纹样承担记录迁徙路线、族群记忆与信仰的功能，故有“穿在身上的史书”之说。挑花以平纹麻布为底、数纱施针，十字针法为基础，兼用鱼骨针、鱼刺针、豆花针等十余种。2006年贵阳花溪苗绣列入第一批国家级非遗；近年通过培训班与传习所扩大传承基数，作品进入博物馆与设计市场。",
  "meaning": "花溪苗绣最特殊的是“反面挑、正面看”：绣娘在背面依经纬交叉点下针，正面才见完整图案，意味着她必须在脑中完成正反转换——这是一套没有图纸的空间计算。数纱定位、不打底稿，所有坐标都在记忆里，图案靠组合、缩放、旋转不断衍生，故没有两件完全相同。王启萍六十余年的实践与四十余名学生的培养，本质是在技艺尚未被完整文本化之前，先用人数把知识留在身体里；这也提示非遗数字化的边界——能记录纹样，未必能记录手感。",
  "chain": "数纱定位→挑出轮廓→添加内部纹样→填充细部。图案全凭记忆组合与衍生。",
  "herFull": "第一批国家级非遗（2006），申报地区包括贵州省贵阳市花溪区等。",
  "inheritor": [
   {
    "name": "王启萍",
    "role": "第五批国家级代表性传承人"
   }
  ],
