  "peak": "极高",
  "feature": "藏羌织绣是“藏族编织、挑花刺绣”与“羌族刺绣”的合称，分别于2011年和2008年入选国家级非遗。羌绣以花围腰和云云鞋著称，最大的特点是不打稿、不描线、不起样，纹样随针而就——绣娘依记忆中的花样在布上即兴生发，每件都是孤本。针法以平绣、挑花、盘金等二十余种为主，针脚极密：既为装饰，也为加固，围腰与鞋面都是易损部位，密绣等同于耐磨处理，审美与功能在这里不分家。",
