    "a": "不描线，依记忆与即兴判断施针。羌绣的纹样在绣娘心里，起针之后纹样随针而生：想绣一朵花，从花心起针，花瓣一片片往外推，推到哪算哪，每件的构图都不相同。即兴不等于随意——纹样的类型、配色的规矩、部位的禁忌都是固定的，变的是组合与比例。用平绣、挑花、盘金等二十余种针法，按纹样的需要随时换针。",
