  "bio": "杨华珍，藏族编织、挑花刺绣工艺国家级代表性传承人（2011年评定）。母亲藏族、父亲羌族，8岁随母亲学针线，51岁后专职传承，累计培训4000多人，徒弟中8人被评为州级非遗传承人。在映秀成立“杨华珍大师工作室”，作品多次带出国参展，将民族文化与现代元素结合。",
  "history": "羌绣流传于岷江上游羌族聚居区，与藏族编织、挑花刺绣合称藏羌织绣。羌族无文字，刺绣承担族群记忆与身份标识的功能，衣襟、围腰、云云鞋是最集中的装饰部位。2008年汶川地震后，羌绣被纳入文化重建与就业扶持项目，绣娘组织化程度迅速提高；同年羌族刺绣列入第二批国家级非遗，2011年藏族编织、挑花刺绣工艺列入第三批国家级非遗。",
  "meaning": "羌绣不描线、不起样，纹样随针而就——绣娘依记忆中的花样在布上即兴生发，每一件都是孤本。针脚极密，既为装饰，也为加固：围腰、鞋面是易损部位，密绣等同于耐磨处理，审美与功能在这里不分家。灾后重建把羌绣从家庭副业推向订单化生产，杨华珍的培训体系累计带出四千余人，八名徒弟成为州级传承人。这条路径的启示是：生产性保护必须先解决订单与分配，技艺才能在市场中站稳，否则培训越多，流失越快。",
  "chain": "以平绣、挑花、盘金等二十余种针法在服饰穿戴部位施绣，无固定线性流程，依绣娘记忆与即兴判断推进。",
  "herFull": "藏族编织、挑花刺绣工艺2011年国家级非遗；羌族刺绣2008年国家级非遗，申报地区四川省汶川县等。",
