  "feature": "以3—5根马尾毛为芯，用白线紧密缠裹成“马尾线”，沿轮廓盘绣定型，再以平绣、挑花、乱针、跳针等针法填心，形成浅浮雕般的立体肌理，被业界称为“刺绣艺术的活化石”。马尾有弹性、不易折断，缠线后盘在布上，光线下有细微的高光与阴影。缠线是全部工序的命门：力度稍松则马尾外露，稍紧则丝线起皱，一根线废掉就要重来。它把“耐用”写进了美学——背带要经得起婴儿数年的使用与反复浆洗，故以马尾为骨。",
