  "bio": "韦桃花，国家级代表性传承人。3岁跟母亲学搓马尾线，5岁正式学绣，12岁独立绣成第一件马尾绣背带，至今六十余年。带动周边村寨一万余名水族妇女在家门口就业——“不用背井离乡去打工，在家门口，一根马尾、一颗针，就能养活一家人”。工坊同时是生产单元与文化展示窗口。",
  "history": "马尾绣流传于贵州三都水族自治县及周边，水语称“马吉”。以马尾毛为芯、丝线缠裹成马尾线，再盘绣成纹，是水族背带（襁褓）与盛装的主要装饰。水书与马尾绣并存，构成水族文化的一体两面：一为文字传统，一为图像传统。2006年列入第一批国家级非遗，被称为“刺绣艺术的活化石”；近年通过工坊与合作社带动上万名妇女居家就业。",
  "meaning": "马尾绣的立体感来自“芯”：马尾毛有弹性、不易折断，缠线后盘在布上形成浅浮雕，光线下有细微的高光与阴影。缠线是全部工序的命门——力度稍松则马尾外露，稍紧则丝线起皱，一根线废掉就得重来。它把耐用写进了美学：背带要经得起婴儿数年的使用与反复浆洗，故以马尾为骨。韦桃花的工坊把生产单元与文化展示合一，一万余名妇女在家门口就业，说明这类高工时技艺的存续，最终取决于它能否成为一种可以养家的手艺。",
  "chain": "缠线→钉线→填芯。缠线力度决定整根线存废；一件马尾绣背带需整整一年、五十二道工序。",
  "herFull": "第一批国家级非遗（2006），编号Ⅷ-25，申报地区贵州省三都水族自治县。",
  "inheritor": [
   {
    "name": "韦桃花",
    "role": "国家级代表性传承人"
   }
  ],
