    "n": "数纱定位",
    "a": "底布是青色土布，数纱定位是挑花的第一步：数清经纬纱的根数，确定图案的中心与边界。不打底稿，全凭数——横数几根、竖数几根，交叉点即落针处。花瑶挑花的图案对称性极强，多以中轴左右对称，所以定位先定中轴。数错一根，整幅图案就偏，且挑上去无法改。",
