  "bio": "沈燕希，省级代表性传承人（部分报道称国家级）。在挑花技艺传习所展示技艺并参与培训班；曾在湖南省两会“代表通道”上携带筒裙展示，指出一件筒裙三四十万针、耗时一年。她推动花瑶挑花进入耳饰、手包、腰带等当代产品，以使用场景的扩展对冲传承断层。花瑶没有文字，挑花是每个女孩的“必修课”，节庆与出嫁时要穿自己挑制的盛装。",
  "history": "花瑶是瑶族的一个分支，聚居湖南隆回虎形山一带。挑花以青色土布为底、五彩丝线为色，数纱下针、十字交叉成型，双面成纹。花瑶没有文字，挑花承担记录历史与信仰的功能，被称为“穿在身上的无字史书”。据考挑花起源可追溯至汉代，明清后趋于成熟；2006年隆回花瑶挑花列入第一批国家级非遗。近年通过传习所、非遗工坊与文创转化延续。",
  "meaning": "一件筒裙三四十万针、耗时一年，挑花的成本几乎全部是时间。数纱定位、不打底稿，图案存于记忆，靠组合、缩放、旋转不断生发，同一个纹样在不同绣娘手里会长出不同变体。双面成纹要求每一次起针落针都正反兼顾，等于同时绣两幅。花瑶女孩从小学习挑花，节庆与出嫁时穿自己挑制的盛装，技艺与人生仪礼绑定，这是它最牢固的传承机制；沈燕希把挑花带进耳饰、手包、腰带，是以使用场景的扩展对冲传承断层。",
  "chain": "数纱定位→十字交叉挑绣→逐层扩展。图案藏于记忆，通过组合、缩放、旋转不断衍生。",
  "herFull": "第一批国家级非遗（2006），申报地区湖南省隆回县。",
