  "feature": "“一高四多”——工艺要求高，工序多、纳底花样多、绱鞋方法多、品种多。制底有切底、包签、圈边、纳底、锤底5道工序，整个制作过程需90余道，使用工具近40种。纳底是核心：麻线沿边缘约1.5毫米一针，每平方寸81针，一只鞋底要纳两到三天；针距与深度决定鞋底的密度、弹性与耐穿度，机器可以模仿针脚，却给不了“该紧处紧、该松处松”的分寸。锤底是隐性工序：锤打让鞋底平整服帖，也把麻线的张力重新分布。男鞋底35层、女鞋31层。",
