    "a": "按鞋样切底：把袼褙按纸样切成鞋底的形状，切刀要立直，一刀到底，切边要齐——边不齐，包签时就包不匀。包签是用白布把鞋底的边缘包住，包得要紧、要匀，不能起皱。圈边是在包签之外再加一道边线，把鞋底的轮廓勾出来。这三道做完，鞋底的形就定了。",
    "t": "切刀",
    "h": "—",
    "d": "中",
    "k": "切边不齐则包签不匀，圈边就歪，鞋底的形从这一步就定了。",
