    "n": "绱鞋",
    "a": "把鞋帮缝到鞋底上，有正绱、反绱、明绱三种手法。正绱是帮在外、缝线藏在帮内，成品干净；反绱是先把鞋翻过来缝，再翻正，缝线完全隐藏，最费工；明绱是缝线露在外面，作为装饰。三种手法各有适用：礼服鞋多用反绱，日常鞋用正绱。绱的时候针脚要匀、要藏，帮底要对齐，一圈缝完不能有皱。",
