  "bio": "任晨阳，第五代传承人，80后。2005年大学毕业后进入内联升，2009年正式拜师国家级传承人何凯英。第一次给顾客量脚订做布鞋，“一共做了三四次，顾客才最终合脚”——这句话后来成了他理解这门手艺的起点。他成立非遗工作室，推动IP联名，联名款上线即售罄，米兰时装周设计师主动洽谈合作，以市场需求反哺手工纳底技艺的存续。",
  "history": "内联升创立于清咸丰三年（1853），创始人赵廷，店名取“连升三级”之意，以朝靴起家，为京官定制；民国后转做大众布鞋，形成“一高四多”的工艺体系。1950年代公私合营，九十年代后老字号改制；2008年千层底布鞋制作技艺列入第二批国家级非遗。近年以 IP 联名与国潮设计重新进入年轻市场，联名款上线即售罄。",
  "meaning": "千层底的核心是“纳”：麻线沿边缘约一点五毫米一针，每平方寸八十一针，一只鞋底要纳两三天。针距与深度决定鞋底的密度、弹性与耐穿度，全凭手感——机器可以模仿针脚，却给不了那种该紧处紧、该松处松的分寸。锤底是另一道隐性工序：锤打让鞋底平整服帖，也把麻线的张力重新分布。任晨阳的联名与 IP 化，是把老字号的信任转译成当代设计语言。先让人愿意穿，技艺才有订单；这一顺序不能颠倒。",
  "chain": "前期准备→制底（切底、包签、圈边、纳底、锤底）→制帮及制垫→绱鞋。纳一只鞋底需两到三天。",
  "herFull": "第二批国家级非遗（2008），申报地区北京市。",
  "inheritor": [
   {
    "name": "任晨阳",
    "role": "第五代传承人，80后"
   }
  ],
