  "bio": "李金善，第三批国家级代表性传承人，全国“五一”劳动奖章获得者。1974年进入北京盛锡福帽厂，师从有祖传皮毛裁制技艺的李文耕，学习选料、配活、平皮、裁制等传统技艺，练就挑皮、走刀的绝活。先后为党和国家领导人制作皮帽，负责修补故宫博物院龙袍和宋庆龄故居的孙中山海龙皮帽。编写《皮毛、皮帽裁剪制作工艺流程》，推动工艺流程标准化，培养出马万兰等一批能工巧匠。",
  "history": "盛锡福1911年由刘锡三创办于天津，二十世纪三十年代在北京、南京、上海等地设分号，形成南北呼应的帽业网络。创始人不断聘请高级技师、吸收国内外制帽技术，皮帽制作自成一路。1950年代后公私合营；2008年盛锡福皮帽制作技艺列入第二批国家级非遗，编号Ⅷ-113。李金善等传承人编写工艺流程，推动手工环节的标准化。",
  "meaning": "皮帽的难处在于“活”：挑皮要按毛色、毛长、密度分档，配活要顺着毛被走向拼接，使成品看不出接缝——这一步没有图纸，只有经验。剌皮用走刀，一刀下去可能损失千余元的料，容错空间极低。李金善把可标准化的部分（选料标准、工序顺序、检验要点）写进规程，把不可替代的判断（毛性、刀感、缝合松紧）留给师徒，这种部分标准化是手工技艺进入现代生产的可行解——既不失去手感，也不拒绝效率。",
  "chain": "挑皮→配活→裁剪→缝制→整修。配皮、挑皮、吹风、刷水、平皮、刺皮、手针齐缝儿都是大项，细项更多。",
  "herFull": "第二批国家级非遗（2008），编号Ⅷ-113，申报地区北京市东城区。",
