  "feature": "以侗布（亮布）为核心面料：蓝靛反复浸染后反复捶打，使纤维表面压平、定向反光，再涂蛋清或牛皮胶封住，才有近乎金属的质感，古称蛋浆布。工序为蓝靛染色、捶布、涂蛋清或牛皮胶、复捶、裁剪、织锦镶边、银饰搭配。亮布的难点在“匀”：力不匀则光泽斑驳，捶过头则纤维断裂。侗锦古称“纶织”，以经纬显花，为女性盛装镶边提供技术支撑；女性盛装多配银饰。侗锦有逾两千年历史，是中国著名织锦之一。",
