  "bio": "粟田梅，侗锦织造技艺国家级代表性传承人，湖南省通道侗族自治县牙屯堡镇枫香村人。15岁创作第一件侗锦作品，2009年被列为侗锦织艺国家级代表性传承人。她长期在村寨办班，培训了几千名织锦爱好者，把侗锦从民族服饰面料推向家纺与家居服饰产业。侗锦有逾两千年历史，古称“纶织”，是侗族女性世代相传的纯手工织物，图案大多取材动植物。",
  "history": "侗族服饰以侗布（亮布）为核心，亮布经蓝靛反复浸染、捶打、涂蛋清或牛皮胶再捶，呈现金属般的光泽，古称蛋浆布。侗锦古称“纶织”，历史可上溯至两千余年前的春秋战国，两汉至唐宋，侗族先民的纺织与印染已形成独特风格。2008年侗锦织造技艺列入第二批国家级非遗；2014年侗族服饰列入第四批国家级非遗。粟田梅等传承人推动侗锦进入家纺与家居服饰产业。",
  "meaning": "亮布的“亮”是捶出来的：蓝靛染透后，反复捶打使纤维表面压平、定向反光，再涂蛋清或牛皮胶封住，才有近乎金属的质感。这道工序的难点在匀——力不匀则光泽斑驳，捶过头则纤维断裂。侗锦提供技术支撑：经纬显花的织造能力，使镶边不只是装饰，而是工艺水平的展示。粟田梅培训数千名织锦爱好者，把侗锦从民族服饰面料拓展到家纺；用途一变，订单结构就变，技艺的存续也就有了产业支点。",
  "chain": "蓝靛染色→捶布→涂蛋清/牛皮胶→复捶→裁剪→织锦镶边→银饰搭配。",
  "herFull": "侗锦织造技艺第二批国家级非遗（2008）；侗族服饰第四批国家级非遗（2014），申报地区包括贵州省黔东南苗族侗族自治州等。",
