  "bio": "说各惹曲（说各妞牛），第五批国家级代表性传承人，凉山州昭觉县人，精通“查尔瓦”（察尔瓦）工艺。阿牛阿呷，彝族毛纺织及擀制技艺非遗传承人、原创独立设计师，2018年携以“擦尔瓦”为设计灵感的“白云间”系列33套服饰亮相中国国际时装周。沙马阿西为州级传承人，昭觉县哈甘乡瓦西村人。",
  "history": "彝族分布于川滇黔桂，支系众多，服饰形制差异极大，是支系识别的活标本。凉山彝族尚黑崇火，男子以头帕与察尔瓦（披毡）为标志，女子以百褶裙、头帕与银饰区分支系与婚否。羊毛擀毡工艺有千年以上历史，2007年彝族毛纺织及擀毡技艺列入四川省省级非遗；2014年彝族服饰列入第四批国家级非遗。近年通过国际时装周与设计联名进入当代视野。",
  "meaning": "察尔瓦是彝族服饰的技术原点：羊毛不纺不织，直接擀压成毡，防水、耐磨，可披可盖，是高山生活的实用解。擀毡的关键在湿度与力度——羊毛在热水与压力下鳞片交缠，毡化程度全凭手感。彝族服饰的支系差异不是装饰趣味，而是社会结构的外化：一眼可辨的形制，承担着你是谁、从哪来、婚否的信息功能。说各惹曲守住手工作坊，阿牛阿呷把察尔瓦带上国际时装周，一个保技艺的纯度，一个拓场景的宽度，二者并不冲突。",
  "chain": "羊毛擀制（察尔瓦）→纺织/染布→裁剪→刺绣/镶边→银饰搭配→整体穿着。",
  "herFull": "第四批国家级非遗（2014）；彝族毛纺织及擀制技艺省级非遗（2007）。",
